// mock these globally used functions
import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import ResizeObserver from "resize-observer-polyfill";
import { afterEach, beforeEach, expect, test, vi } from "vitest";
import { ValidationError } from "@formbricks/types/errors";

// mock our useSignOut hook directly to avoid auth issues in tests
vi.mock("@/modules/auth/hooks/use-sign-out", () => ({
  useSignOut: () => ({
    signOut: vi.fn().mockResolvedValue(undefined),
  }),
}));

// Make ResizeObserver available globally (Vitest/Jest environment)
// This is used by radix-ui
if (!global.ResizeObserver) {
  global.ResizeObserver = ResizeObserver;
}

// Mock useIsMobile hook that depends on window.matchMedia
vi.mock("@/modules/ui/hooks/use-mobile", () => ({
  useIsMobile: vi.fn().mockReturnValue(false),
}));

// mock react toast

vi.mock("react-hot-toast", () => ({
  default: {
    success: vi.fn(),
    error: vi.fn(),
  },
  toast: {
    success: vi.fn(),
    error: vi.fn(),
  },
  success: vi.fn(),
  error: vi.fn(),
}));

// mock react cache
const testCache = <T>(func: T) => func;

vi.mock("react", async () => {
  const react = await vi.importActual<typeof import("react")>("react");

  return {
    ...react,
    cache: testCache,
  };
});

// mock next/router navigation
vi.mock("next/navigation", async () => {
  const actual = await vi.importActual<typeof import("next/navigation")>("next/navigation");

  return {
    ...actual,
    useRouter: () => ({
      push: vi.fn(),
      replace: vi.fn(),
      back: vi.fn(),
      forward: vi.fn(),
      prefetch: vi.fn(),
      refresh: vi.fn(),
    }),
    notFound: vi.fn(),
    redirect: vi.fn(),
    useSearchParams: vi.fn(),
    usePathname: vi.fn(),
  };
});

// mock server-only
vi.mock("server-only", () => {
  return {};
});

// mock server actions that might be called in tests
vi.mock("@/modules/auth/actions/sign-out", () => ({
  logSignOutAction: vi.fn().mockResolvedValue(undefined),
}));

// mock prisma client

vi.mock("@formbricks/database/prisma", async () => {
  const actual = await vi.importActual<typeof import("@formbricks/database/prisma")>(
    "@formbricks/database/prisma"
  );

  return {
    ...actual,
    Prisma: actual.Prisma,
    PrismaClient: class {
      // Better Auth 1.7 seeds its `oauthResource` rows when the oauthProvider plugin initialises
      // (ENG-2343), which happens on any import of modules/auth/lib/auth.ts. Against this stub the
      // adapter would otherwise throw `Model oauthResource does not exist in the database` as an
      // unhandled error in every such test file — noise that would sit in the suite forever and
      // mask a real failure later. A read that returns nothing lets seeding complete quietly;
      // nothing here asserts on it, and the real behaviour is covered against a real database.
      oauthResource = {
        findMany: () => Promise.resolve([]),
        findFirst: () => Promise.resolve(null),
        findUnique: () => Promise.resolve(null),
        create: (args: { data: unknown }) => Promise.resolve(args.data),
        createMany: () => Promise.resolve({ count: 0 }),
        update: (args: { data: unknown }) => Promise.resolve(args.data),
        upsert: (args: { create: unknown }) => Promise.resolve(args.create),
      };

      $connect() {
        return Promise.resolve();
      }
      $disconnect() {
        return Promise.resolve();
      }
      $extends() {
        return this;
      }
    },
  };
});

// mock URL object

if (typeof URL.revokeObjectURL !== "function") {
  URL.revokeObjectURL = () => {};
}

if (typeof URL.createObjectURL !== "function") {
  URL.createObjectURL = () => "blob://fake-url";
}

// mock crypto function used in the license check utils, every component that checks the license will use this mock
// also used in a lot of other places too
vi.mock("crypto", async () => {
  const actual = await vi.importActual<typeof import("crypto")>("crypto");

  return {
    ...actual,

    createHash: () => ({
      update: vi.fn().mockReturnThis(),
      digest: vi.fn().mockReturnValue("fake-hash"),
    }),
    default: {
      ...actual,
      createHash: () => ({
        update: vi.fn().mockReturnThis(),
        digest: vi.fn().mockReturnValue("fake-hash"),
      }),
    },
  };
});

// mock next/headers to prevent audit log system from failing
vi.mock("next/headers", () => ({
  headers: () => ({
    get: () => null,
    has: () => false,
    keys: () => [],
    values: () => [],
    entries: () => [],
    forEach: () => {},
  }),
  cookies: () => ({
    get: () => null,
    has: () => false,
    getAll: () => [],
    set: () => {},
    delete: () => {},
  }),
}));

beforeEach(() => {
  vi.resetModules();
  vi.resetAllMocks();
});

afterEach(() => {
  // React Testing Library normally registers this itself, but it looks for a *global* `afterEach`
  // (`typeof afterEach === 'function'`) and this project runs with vitest `globals: false` — so its
  // auto-cleanup never installs. Without it, every render()/renderHook() stays mounted for the rest
  // of the file: components from earlier tests keep firing timers, keep responding to window events,
  // and keep calling shared module mocks, so a later test's assertions can count work it never did.
  // Called here rather than as its own afterEach so the order against clearAllMocks is explicit:
  // unmount first, while mock implementations are still in place for any cleanup effects.
  cleanup();
  vi.clearAllMocks();
});

// Registers a test; nothing to await, and no caller awaits it.
export const testInputValidation = (service: (...args: any[]) => unknown, ...args: any[]): void => {
  test("throws a ValidationError if the inputs are invalid", async () => {
    await expect(service(...args)).rejects.toThrow(ValidationError);
  }, 15000);
};

